# Initially generated by GitHub Copilot.
"""Bot edit: replace קו"כ-אם (trivial k/q) with מ:קו"כ-אם-2.

Old format: {{קו"כ-אם|pointed-ketiv|2=<source-indicator>=pointed-qere}}
New format: {{מ:קו"כ-אם-2|pointed-ketiv|unpointed-ketiv|pointed-qere|מקורות=<source-indicator>}}

Edge cases (logged as warnings, old template left in place):
  - Param 1 contains an inner template (e.g. {{מ:קמץ|...}})
  - Param 2 has an atypical value (qere sub-string contains space or '(')

Special case (omit מקורות= entirely):
  - Param 2 starts with 'קרי=' (policy-based, no manuscript source)

Warnings are accumulated in _warnings and retrieved via get_warnings().
The caller is responsible for writing them to a file.

See ws_bot_edit_history.md and MAM-basics#55.
"""

from functools import partial

from pycmn import ws_tmpl1 as wtp1
from pycmn.my_utils import dv_dispatch
from pycmn.my_utils import dv_map
from pycmn.my_utils import sl_map
from pycmn.my_utils import sum_of_map
from pycmn.shrink import shrink
from py_misc import hebrew_letter_words as hlw
from pyws import ws_fmt_2_back_to_wikitext as btw
from pyws import ws_get_bk_in_both_fmts as wsin

_OLD_TMPL_NAME = 'קו"כ-אם'
_NEW_TMPL_NAME = 'מ:קו"כ-אם-2'

# Module-level context set per chapter during edit_page_text.
_ctx = {"bk39id": None, "he_chnu": None}
_warnings = []

_ATYPICAL = object()  # sentinel for _parse_param2


def _parse_param2(s):
    """Parse param 2 string. Returns (source, qere) or _ATYPICAL.

    source is None for the policy-based case (no manuscript source).
    """
    eq_idx = s.find("=")
    if eq_idx == -1:
        return _ATYPICAL
    source_key = s[:eq_idx]
    qere = s[eq_idx + 1 :]
    # Atypical: qere contains a space or '(' (e.g. Eccl 10:10 free-text note)
    if " " in qere or "(" in qere:
        return _ATYPICAL
    # Policy-based (no manuscript source): source_key is exactly "קרי"
    if source_key == "קרי":
        return None, qere
    return source_key, qere


def get_warnings():
    """Return accumulated warning entries (list of dicts)."""
    return list(_warnings)


def _warn(reason, old_tmpl):
    _warnings.append(
        {
            "bk39id": _ctx["bk39id"],
            "he_chnu": _ctx["he_chnu"],
            "reason": reason,
            "old_tmpl": old_tmpl,
        }
    )


def _transform_kq_triv(tmpl):
    """Transform one קו"כ-אם template to מ:קו"כ-אם-2."""
    assert wtp1.template_len(tmpl) == 3

    # Param 1: pointed ketiv — must be a plain string
    param1_el = wtp1.template_element(tmpl, 1)
    if len(param1_el) != 1 or not isinstance(param1_el[0], str):
        _warn("complex-param-1", tmpl)
        return [tmpl]
    pointed_ketiv = param1_el[0]

    # Param 2: named param "2=<source-indicator>=<qere>"
    param2_el = wtp1.named_template_element(tmpl, 2, "2")
    if len(param2_el) != 1 or not isinstance(param2_el[0], str):
        _warn("complex-param-2", tmpl)
        return [tmpl]
    param2_str = param2_el[0]

    parse_result = _parse_param2(param2_str)
    if parse_result is _ATYPICAL:
        _warn("atypical-param-2", tmpl)
        return [tmpl]
    source, pointed_qere = parse_result

    unpointed_ketiv = hlw.letters_and_maqafs(pointed_ketiv)

    new_els = [
        [_NEW_TMPL_NAME],
        [pointed_ketiv],
        [unpointed_ketiv],
        [pointed_qere],
    ]
    if source is not None:
        new_els.append([f"מקורות={source}"])
    return [wtp1.mktmpl(new_els)]


def _pass_thru(val):
    return val


def _pass_thru_as_singleton(val):
    return [val]


def _edit_wtseq(wandlers, wtseq):
    return shrink(sum_of_map((_edit_wtel, wandlers), wtseq))


def _edit_wtel(wandlers, wtel):
    if isinstance(wtel, str):
        return wandlers["string"](wtel)
    if wtp1.is_abtag(wtel):
        return [wtel]
    return _edit_tmpl_call(wandlers, wtel)


def _edit_tmpl_call(wandlers, tmpl):
    if wandler := wandlers.get(wtp1.template_name(tmpl)):
        return wandler(tmpl)
    return _recurse_on_args(_get_wandlers, tmpl)


def _recurse_on_args(get_wandlers_fn, tmpl):
    tmpl_els_in = wtp1.template_elements(tmpl)
    assert isinstance(tmpl_els_in, list)
    wandlers = get_wandlers_fn()
    tmpl_args_out = sl_map((_edit_wtseq, wandlers), tmpl_els_in[1:])
    tmpl_els_out = [tmpl_els_in[0], *tmpl_args_out]
    return [wtp1.mktmpl(tmpl_els_out)]


def _get_wandlers():
    return _WANDLERS


def _edit_a_chap_body(vandlers, chap_body):
    return dv_map((_edit_a_plb_verse, vandlers), chap_body)


def _edit_a_plb_verse(vandlers, plb_verse):
    return dv_dispatch(vandlers, plb_verse)


_WANDLERS = {
    "string": _pass_thru_as_singleton,
    _OLD_TMPL_NAME: _transform_kq_triv,
}

_VANDLERS = {
    "prefix": _pass_thru,
    "location": _pass_thru,
    "verse-body": partial(_edit_wtseq, _WANDLERS),
}

_CANDLERS = {
    "ws-chap-noinclude-header": _pass_thru,
    "ws-chap-body": partial(_edit_a_chap_body, _VANDLERS),
    "ws-chap-good-ending": _pass_thru,
    "ws-chap-noinclude-footer": _pass_thru,
    "ws-chap-category": _pass_thru,
}


def edit_cif2(he_chnu, cif2):
    """Transform cif2 AST: replace קו"כ-אם with מ:קו"כ-אם-2."""
    out_cif2 = dv_dispatch(_CANDLERS, cif2)
    return out_cif2, btw.big_str(he_chnu, out_cif2)


def edit_page_text(bk39id, he_chnu, page_text):
    """Transform raw page text: replace קו"כ-אם with מ:קו"כ-אם-2."""
    _ctx["bk39id"] = bk39id
    _ctx["he_chnu"] = he_chnu
    cif2 = wsin.get_chap_in_fmt_2(page_text.splitlines())
    _out_cif2, big_str = edit_cif2(he_chnu, cif2)
    return big_str
